// Generated by @canonical/summon-component:react v0.43.0

import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import FilterBar from "./FilterBar.js";

describe("FilterBar", () => {
  it("is a named group holding the facets, then the chips", () => {
    render(
      <FilterBar
        chips={<span>zone 1</span>}
        facets={<button type="button">Zone</button>}
      />,
    );
    const bar = screen.getByRole("group", { name: "Facets" });
    expect(bar.tagName).toBe("FIELDSET");
    expect(bar.closest<HTMLElement>("[data-region]")?.dataset.region).toBe(
      "filter-bar",
    );
    const slots = [...bar.querySelectorAll("[data-slot]")].map(
      (slot) => (slot as HTMLElement).dataset.slot,
    );
    expect(slots).toEqual(["facets", "chips"]);
  });

  it("renders the chips only when given", () => {
    render(<FilterBar facets="Zone" />);
    expect(
      screen.getByRole("group").querySelector('[data-slot="chips"]'),
    ).toBeNull();
  });

  it("applies custom className and passes native props through", () => {
    render(
      <FilterBar className="custom-class" data-testid="bar" facets="Zone" />,
    );
    const bar = screen.getByTestId("bar");
    expect(bar.className).toContain("ds filter-bar");
    expect(bar.className).toContain("custom-class");
  });
});
